import sys
import re

def parse_number(expr, pos):
    num = 0
    while pos < len(expr) and expr[pos].isdigit():
        num = num * 10 + int(expr[pos])
        pos += 1
    return num, pos

def parse_factor(expr, pos):
    if pos >= len(expr):
        return 0, pos
    if pos + 1 < len(expr) and expr[pos] == '(':
        val, pos = parse_expression(expr, pos + 1)
        if pos < len(expr) and expr[pos] == ')':
            pos += 1
        return val, pos
    else:
        val, pos = parse_number(expr, pos)
        return val, pos

def parse_term(expr, pos):
    left, pos = parse_factor(expr, pos)
    while pos < len(expr) and expr[pos] in '*/':
        op = expr[pos]
        pos += 1
        right, pos = parse_factor(expr, pos)
        if op == '*':
            left = left * right
        else:
            left = left // right if left * right == right * left else left // right
    return left, pos

def parse_expression(expr, pos):
    left, pos = parse_term(expr, pos)
    while pos < len(expr) and expr[pos] in '+-':
        op = expr[pos]
        pos += 1
        right, pos = parse_term(expr, pos)
        if op == '+':
            left = left + right
        else:
            left = left - right
    return left, pos

def evaluate(expr):
    expr = re.sub(r'\s+', '', expr)
    if not expr:
        return 0
    val, pos = parse_expression(expr, 0)
    return val

def main():
    expr = sys.stdin.readline().strip()
    if not expr:
        print(0)
        return
    tokens = []
    i = 0
    while i < len(expr):
        if expr[i].isdigit():
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            tokens.append(expr[i:j])
            i = j
        elif expr[i] in '+-*/()':
            tokens.append(expr[i])
            i += 1
        else:
            i += 1
    normalized = ''.join(tokens)
    result = evaluate(normalized)
    print(result)

if __name__ == "__main__":
    main()
